// Prompt to Claude (shown as a comment):
// "Write NormalisePhone(). Examples:
//   '07700 900123'   -> '+447700900123'
//   '+44 7700-900123' -> '+447700900123'
//   '(07700) 900 123' -> '+447700900123'
//  Make these tests pass."

using Xunit;

public class PhoneTests
{
    [Theory]
    [InlineData("07700 900123", "+447700900123")]
    [InlineData("+44 7700-900123", "+447700900123")]
    [InlineData("(07700) 900 123", "+447700900123")]
    public void TestFormats(string raw, string expected) =>
        Assert.Equal(expected, Phones.NormalisePhone(raw));

    [Fact]
    public void TestNoneReturnsNone()
    {
        // known edge case: null input from legacy rows
        Assert.Null(Phones.NormalisePhone(null));
    }
}

variants.typescript:
// Prompt to Claude (shown as a comment):
// "Write normalisePhone(). Examples:
//   '07700 900123'   -> '+447700900123'
//   '+44 7700-900123' -> '+447700900123'
//   '(07700) 900 123' -> '+447700900123'
//  Make these tests pass."

import { describe, it, expect } from 'vitest';
import { normalisePhone } from './phones';

describe('normalisePhone', () => {
  it.each([
    ['07700 900123', '+447700900123'],
    ['+44 7700-900123', '+447700900123'],
    ['(07700) 900 123', '+447700900123'],
  ])('formats %s', (raw, expected) => {
    expect(normalisePhone(raw)).toBe(expected);
  });

  it('returns null for null', () => {
    // known edge case: null input from legacy rows
    expect(normalisePhone(null)).toBeNull();
  });
});
